// Parse the model's JSON and refuse anything that would publish badly.
//
// Faults are RECORDED, not thrown. A throw here aborted the entire execution,
// so one bad generation destroyed every row still queued behind it. A failing
// row is now marked needs_review with a reason, the sheet records it, and the
// Supabase insert is skipped for that row alone.
// The sheet row must be read back from the loop, NOT from item.json.
//
// Blog Writer Agent is a chain node: its output is only { text }. Spreading
// item.json here therefore spread the model's reply, not the queue row, so
// blog_id, category and title were silently lost at the agent. That is why
// categories arrived empty in Supabase and why Mark Blog Row Done matched on
// an empty blog_id and updated nothing -- one cause, both symptoms.
const out = [];

for (const item of $input.all()) {
  // The queue row this iteration is working on.
  //
  // Must be .first(), not .item. This Code node runs once for ALL items
  // ($input.all()), and $('Node').item needs paired-item resolution, which is
  // only valid in per-item mode -- it throws here. A previous version caught
  // that and fell back to {}, which silently dropped blog_id and category
  // again: categories arrived empty and the sheet update matched no row.
  // Loop Blog Rows emits exactly one row per iteration, so .first() is
  // unambiguous and works in this mode.
  let src = {};
  let srcError = '';
  try {
    src = $('Loop Blog Rows').first().json || {};
  } catch (e) {
    srcError = 'could not read the queue row from Loop Blog Rows: ' + e.message;
  }

  const raw = item.json?.text ?? item.json?.output ?? item.json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  const cleaned = String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();

  const problems = [];
  if (srcError) problems.push(srcError);
  if (!srcError && !src.blog_id) problems.push('queue row has no blog_id, so the sheet cannot be updated');

  // The article body arrives AFTER a sentinel, not inside the JSON.
  //
  // Asking for content_html as a JSON string was the real defect: an ordinary
  // attribute like <a href="/category/x"> terminates the JSON string early and
  // the parse dies with "Expected ',' or '}' after property value" thousands of
  // characters into the HTML. Splitting on a marker means the HTML never has to
  // be escaped, and the JSON left over is a few hundred characters of short
  // fields, which is very hard to break.
  const HTML_MARK = '<<<HTML>>>';
  const META_MARK = '<<<META>>>';
  const unfence = (s) => String(s).replace(/^\s*```(?:json|html)?/i, '').replace(/```\s*$/, '').trim();

  let post = null;
  const cut = cleaned.indexOf(HTML_MARK);

  if (cut !== -1) {
    let meta = cleaned.slice(0, cut);
    const m = meta.indexOf(META_MARK);
    if (m !== -1) meta = meta.slice(m + META_MARK.length);
    try {
      post = JSON.parse(unfence(meta));
      post.content_html = unfence(cleaned.slice(cut + HTML_MARK.length));
    } catch (e) {
      post = null;
      problems.push('metadata block is not valid JSON: ' + e.message);
    }
  } else {
    // Older single-object shape, still accepted so an in-flight run does not break.
    try {
      post = JSON.parse(cleaned);
    } catch (e) {
      problems.push('no ' + HTML_MARK + ' marker, and the whole reply is not valid JSON: ' + e.message);
    }
  }

  if (post) {
    const need = ['title', 'slug', 'seo_title', 'meta_description', 'excerpt', 'image_prompt', 'content_html'];
    const missing = need.filter((k) => !post[k] || String(post[k]).trim() === '');
    if (missing.length) problems.push('missing required fields: ' + missing.join(', '));

    const html = String(post.content_html ?? '');
    if (/<h1[\s>]/i.test(html)) problems.push('content_html contains an <h1>; the theme renders the title');
    if (/<script|<style|onerror=|onclick=/i.test(html)) problems.push('content_html contains script, style or an event handler');
    if (String(post.title ?? '').length > 80) problems.push('title too long: ' + String(post.title).length);
    if (String(post.meta_description ?? '').length > 165) problems.push('meta_description too long: ' + String(post.meta_description).length);
    if (post.slug) post.slug = String(post.slug).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  }

  const words = post && post.content_html
    ? String(post.content_html).replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length
    : 0;
  if (words < 350) problems.push('only ' + words + ' words, too thin to publish');

  out.push({ json: {
    ...src,
    post: post || {},
    wordCount: words,
    blog_status: problems.length ? 'needs_review' : 'completed',
    quality_error: problems.join('; '),
  } });
}

return out;

// Runs when Loop Blog Rows finishes, on the "done" output.
//
// This branch was empty, so a run that published nothing looked exactly like a
// run that worked: every node green, no output anywhere. That is the single
// most confusing failure mode this pipeline has, so it now reports itself.
const items = $input.all();
const total = items.length;

const published = [];
const skipped = [];
for (const item of items) {
  const j = item.json;
  const id = j.blog_id || j.title || 'unknown row';
  if (j.blog_status === 'completed') published.push(id);
  else skipped.push(id + ' -- ' + (j.quality_error || 'no reason recorded'));
}

const summary = {
  rows_read: total,
  published: published.length,
  skipped: skipped.length,
  published_ids: published,
  skipped_with_reasons: skipped,
};

if (total > 0 && published.length === 0) {
  summary.warning =
    'Every row was skipped, so nothing reached Supabase. The reason for each is ' +
    'in skipped_with_reasons above, and in the quality_error column of the sheet.';
}

return [{ json: summary }];
